exercises.solution:
OPS = {
    "+": lambda a, b: a + b,
    "-": lambda a, b: a - b,
    "*": lambda a, b: a * b,
    "/": lambda a, b: a / b,
}

def calculate(a, op, b):
    if op not in OPS:
        raise ValueError("неизвестная операция")
    return OPS[op](a, b)

def pipeline(value, *funcs):
    for func in funcs:
        value = func(value)
    return value

def count_calls(func, args_list):
    result = {}
    for arg in args_list:
        r = func(arg)
        result[r] = result.get(r, 0) + 1
    return result

