from functools import wraps


def memoize_with_hits(func):
    cache = {}

    @wraps(func)
    def wrapper(*args):
        if args in cache:
            wrapper.hits += 1
        else:
            wrapper.misses += 1
            cache[args] = func(*args)
        return cache[args]

    def clear():
        cache.clear()
        wrapper.hits = 0
        wrapper.misses = 0

    wrapper.clear = clear
    clear()
    return wrapper

