from functools import wraps


def repeat(times):
    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            result = None
            for _ in range(times):
                result = func(*args, **kwargs)
            return result
        return wrapper
    return decorator

exercises.tests:
def test_values():
    state = {"n": 0}
    @retry(times=4, exceptions=(ConnectionError, TimeoutError))
    def flaky():
        state["n"] += 1
        if state["n"] == 1:
            raise ConnectionError
        if state["n"] == 2:
            raise TimeoutError
        return "ok"
    assert flaky() == "ok" and state["n"] == 3, "Повторы"
    state["n"] = 0
    @retry(times=2, exceptions=(ConnectionError,))
    def dead():
        state["n"] += 1
        raise ConnectionError
    try:
        dead()
    except ConnectionError:
        assert state["n"] == 2, "Ровно times попыток"
    state["n"] = 0
    @retry(times=5, exceptions=(ConnectionError,))
    def wrong():
        state["n"] += 1
        raise ValueError
    try:
        wrong()
    except ValueError:
        assert state["n"] == 1, "Чужие ошибки не повторяются"
        return
    assert False, "ValueError должен пробрасываться"

