from functools import wraps


def validate_range(low, high):
    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            for a in args:
                if not low <= a <= high:
                    raise ValueError(f"{a} вне [{low}, {high}]")
            return func(*args, **kwargs)
        return wrapper
    return decorator

