    a.debug = True
    b = Config()
    assert a is b and b.debug, "Должен быть один объект"
    @singleton
    class Other:
        pass
    assert Other() is not a, "У каждого класса свой объект"

exercises.solution:
def singleton(cls):
    instance = None

    def get_instance(*args, **kwargs):
        nonlocal instance
        if instance is None:
            instance = cls(*args, **kwargs)
        return instance
    return get_instance

