from functools import wraps


def parametrize(cases):
    def decorator(func):
        @wraps(func)
        def run_all():
            failed = 0
            for case in cases:
                try:
                    func(*case)
                except AssertionError:
                    failed += 1
            return failed
        return run_all
    return decorator

